/**
 * Bundled ISO reference lists (generated by scripts/build_reference_data.py).
 */
import countriesJson from './iso3166.json';
import currenciesJson from './iso4217.json';
import { spec } from '../spec/index.ts';

export const countries = countriesJson.countries;
export const currencies = currenciesJson.currencies;
export const isoSources = { countries: countriesJson.source, currencies: currenciesJson.source };

const countrySet = new Set(countries.map((c) => c.code));
const currencySet = new Set(currencies.map((c) => c.code));

/** Non-ISO currency codes the active TPT spec explicitly allows (e.g. CNH), from the spec's currency fields. */
export const tptExtraCurrencies: { code: string; label: string }[] = (() => {
  const seen = new Map<string, string>();
  for (const f of spec.fields) for (const c of f.additionalCodes ?? []) if (!seen.has(c.code)) seen.set(c.code, c.label);
  return [...seen].map(([code, label]) => ({ code, label }));
})();
const extraCurrencySet = new Set(tptExtraCurrencies.map((c) => c.code));

export const isCountry = (code: unknown): boolean => typeof code === 'string' && countrySet.has(code.trim().toUpperCase());
export const isIsoCurrency = (code: unknown): boolean => typeof code === 'string' && currencySet.has(code.trim().toUpperCase());
/** ISO 4217 or one of the extra codes the TPT spec allows. */
export const isTptCurrency = (code: unknown): boolean =>
  isIsoCurrency(code) || (typeof code === 'string' && extraCurrencySet.has(code.trim().toUpperCase()));
